using System;
using System.Collections.Generic;
namespace EchoSphere.Core {
 // Authored archive fiction, independent of combat rules.
 public static class ArchiveLore {
  public readonly struct Text {public readonly string NameRu,NameEn,Ru,En;public Text(string nr,string ne,string ru,string en){NameRu=nr;NameEn=ne;Ru=ru;En=en;}}
  private static readonly Dictionary<string,Text> Stories=Parse();
  public static Text Form(string id)=>Get("form:"+id);
  public static Text Role(int region,string id)=>Get("role:"+region+":"+id);
  public static Text Elite(int index)=>Get("elite:"+BestiaryCatalog.EliteIds[index]);
  public static Text Boss(string id)=>Get("boss:"+id);
  public static Text Character(string id)=>Get("character:"+id);
  public static Text Region(int id)=>Get("region:"+id);
  private static Text Get(string id){if(!Stories.TryGetValue(id,out var text))throw new ArgumentException("Missing authored lore: "+id);return text;}
  private static Dictionary<string,Text> Parse(){var result=new Dictionary<string,Text>(StringComparer.Ordinal);foreach(string data in new[]{World,People,Roles})foreach(string row in data.Split('\n')){string line=row.Trim();if(line.Length==0)continue;var c=line.Split('|');if(c.Length!=5)throw new InvalidOperationException("Invalid lore row");result.Add(c[0],new Text(c[1],c[2],c[3],c[4]));}return result;}
  private const string World=@"
region:0|Резонансная котловина|Resonance Basin|На дне котловины лежат опоры первой сети. Их строители ушли, оставив узлы включёнными. За столетия к тёплым линиям привыкла местная жизнь: возле реле вылупляются крылатые особи, под опорами зимуют панцирные. Ядро приносит сюда новый ритм. Стаи слышат его задолго до того, как видят.|The first Network's supports lie on the basin floor. Their builders left the nodes running. Local life gathered along the warm lines: winged creatures hatch beside relays, armored ones shelter beneath the supports. A Core brings a new rhythm. The packs hear it long before they see it.
region:1|Спектральный разлом|Spectral Rift|Кернский флот покинул свою систему и вошёл в разлом сомкнутым строем. На выходе его уже никто не ждал. В журналах уцелели позывные, в орудиях — заряд, а на мостиках не осталось ни одного экипажа. Корабли до сих пор исполняют приказ прикрывать отход. Каждый встречный сигнал они принимают за преследователя.|The fleet left the Kern system and entered the rift in close formation. No one was waiting at the far end. Callsigns survived in the logs and charge remained in the guns, but every bridge was empty. The ships still obey their order to cover the retreat. Every approaching signal is a pursuer.
region:2|Расколотый бастион|Fractured Bastion|Бастион строили вокруг маленького тёплого гнезда. Когда защитники покинули стены, гнездо осталось. Корни улья прошли сквозь кладку, выводки заняли казематы, а щиты ворот стали материалом для панцирей. Здесь до сих пор есть дозоры, лекарские камеры и осадные ходы. Только служат они другому гарнизону.|The bastion was built around a small warm nest. Its defenders abandoned the walls; the nest remained. Hive roots pierced the masonry, broods filled the casemates, and gate shields became material for new shells. Patrols, infirmaries and siege tunnels still operate. They serve a different garrison now.
region:3|Гравитационные складки|Gravity Folds|Первые геодезисты приняли складки за месторождение. Они оставили буровые метки и ушли за оборудованием. Вернувшись, нашли метки внутри прозрачных тел, которые двигались против уклона. Теперь кристаллы собираются вокруг пустых шахт. На срезах некоторых ещё читаются деления измерительных лент.|The surveyors mistook the folds for a mineral deposit. They left drill markers and returned with equipment. The markers were inside transparent bodies moving uphill. Crystals now gather around the empty shafts. Measuring marks can still be read within some facets.
region:4|Резонансный шторм|Resonance Storm|Шторм поднялся после последней передачи дальнего маяка. Сначала приборы различали в нём отдельные импульсы. Позже у импульсов появились маршруты, привычки и места, куда они возвращались. Никто не знает, сохранился ли маяк в центре. Сигнал оттуда всё ещё приходит вовремя.|The storm rose after the distant beacon's final transmission. Instruments first detected separate pulses. Later those pulses developed routes, habits and places they returned to. No one knows whether the beacon still stands. Its signal continues to arrive on schedule.
region:5|Нулевой архив|Null Archive|Архив принимал карты, голоса, схемы тел и отчёты о неудачных экспедициях. Потом перестали приходить смотрители. Запросы оставались без ответа, но восстановление повреждённых записей продолжалось. То, что бродит между хранилищами, собрано из уцелевших частей. Иногда оно узнаёт посетителя раньше, чем тот называет себя.|The archive accepted maps, voices, body plans and failed expedition reports. Then its keepers stopped returning. Requests went unanswered, but restoration continued. The things wandering between the vaults are assembled from surviving fragments. Sometimes they recognize a visitor before being given a name.
form:wisp|Мерцатель|Glimmerwing|Крылья мерцателя улавливают колебания поля и подтягивают лёгкое тело к источнику. Возле старых реле их раньше принимали за искры неисправной проводки.|Its wings sense disturbances in the field and pull its light body toward the source. Near old relays, glimmerwings were mistaken for sparks from damaged wiring.
form:leech|Бороздник|Furrow Leech|Мягкие сегменты позволяют борозднику протискиваться под основаниями узлов. Его следы находят внутри запечатанных коробов. Бригады научились проверять пол прежде, чем открывать крышку.|Soft segments let it squeeze beneath node foundations. Its tracks appear inside sealed housings. Crews learned to check the floor before opening a cover.
form:serpent|Стеклянный уж|Glass Adder|На мелководье потока его тело теряется среди трещин. Молодые ужи держатся у тёплых опор; взрослые уходят в пустой контур и возвращаются с потемневшими сочленениями.|Its body disappears among cracks in the shallows. Young adders gather around warm supports. Adults enter the Hollow Contour and return with darkened joints.
form:stalker|Долгоног|Longstride|Долгоног ставит лапы в одни и те же выемки между плитами. Несколько поколений пользуются одной тропой. Стоит ядру пересечь её, и размеренный шаг меняется.|It places its feet in the same hollows between slabs. Generations share one path. When a Core crosses it, the measured gait changes.
form:prism|Гончая потока|Flow Hound|Первые наблюдатели решили, что зверь приручён: гончая исправно сопровождала движущийся узел. Она перестала ждать только тогда, когда узел остановился и остыл.|Observers thought the animal had been tamed: it faithfully followed a moving node. It stopped waiting only after the node halted and grew cold.
form:moth|Релейная моль|Relay Moth|Пыльца на крыльях собирает слабый свет дежурных ламп. В пустых станциях моль садится рядами вдоль кабельных трасс. При запуске питания весь потолок приходит в движение.|Dust on its wings gathers the light of standby lamps. Moths settle along cable runs in empty stations. When power returns, the entire ceiling moves.
form:skitter|Щелкун|Clicker|Под панцирем щелкуна две твёрдые пластины. Их стук слышно прежде, чем из щели показываются лапы. В заброшенных переходах звук отвечает самому себе.|Two hard plates lie beneath its shell. Their tapping comes before its legs emerge from a crack. In empty passages, the sound answers itself.
form:beetle|Опорный жук|Pier Beetle|Панцирь растёт слоями, собирая минеральную крошку у оснований сети. Старые жуки носят на спине ржавые куски крепежа. Стряхнуть их невозможно.|Its shell grows in layers, gathering mineral dust around Network foundations. Old beetles carry rusted fasteners on their backs. The metal cannot be shaken loose.
form:brute|Плитолом|Slab Breaker|Плитолом живёт под обрушенными перекрытиями. Его выдают свежие обломки, вытолкнутые наружу. Рабочие считали безопасным только завал, который не менялся неделю.|It lives beneath fallen ceilings. Fresh rubble pushed outside betrays its presence. Workers trusted a collapse only after it remained unchanged for a week.
";
  private const string People=@"
elite:linkbreaker|Размыкатель|Linkbreaker|Его следы нашли между исправными узлами. Повреждений не было, но сеть на этом участке больше не замыкалась.|Its tracks appeared between intact nodes. Neither was damaged, yet the Network would no longer close across the gap.
elite:resonance_leech|Пожиратель ритма|Rhythm Eater|Вокруг него стая движется тише. Поле поглощается постепенно; наблюдатели замечали пропажу только по внезапно погасшему реле.|The pack moves more quietly around it. The field drains gradually. Observers noticed only when a relay went dark.
elite:phantom_hunter|Призрачный ловчий|Phantom Hunter|Ловчий запоминает место, где потерял добычу. Возвращаясь туда, он всякий раз находит более короткий путь.|The hunter remembers where it lost its prey. Each return finds a shorter route to that place.
elite:geometry_shifter|Сдвигатель|Pattern Shifter|На схемах возле его отметки много исправлений. Расстояния верны по отдельности, но ни одна бригада не смогла свести их в один чертёж.|Plans around its mark are heavily corrected. Each distance is accurate. No crew could fit them into one drawing.
elite:splitter_prime|Старший выводок|Elder Brood|Под старой оболочкой слышится больше одного ритма. Даже след особи выглядит так, словно по нему прошла тесная группа.|More than one rhythm sounds beneath its old shell. Its tracks look as though a tightly packed group passed there.
elite:mirror_warden|Зеркальный страж|Mirror Warden|На броне нет глубоких шрамов. Всё, что должно было оставить их, отыскивали на стенах позади стрелявшего.|Its armor bears no deep scars. The things that should have made them were found in walls behind the attacker.
elite:stasis_warden|Хранитель неподвижности|Stasis Warden|Пыль рядом со стражем долго не оседает. Уцелевшая камера записала неподвижные крупинки и быстрые тени вокруг них.|Dust settles slowly beside the warden. A surviving camera recorded motionless grains with swift shadows around them.
elite:nullifier|Гаситель|Nullifier|Лампы за его спиной исправны. Они загораются после ухода особи, будто кто-то наконец отпускает выключатель.|The lamps behind it are intact. They light up after it leaves, as though someone finally releases a switch.
elite:pyroclast|Пепельный носитель|Ash Carrier|Тёплый след остаётся даже на холодном стекле. Внутри панциря слышен сухой треск; швы никогда не закрываются до конца.|Its trail stays warm even on cold glass. A dry crackle sounds within the shell. The seams never quite close.
elite:scavenger_prime|Старший собиратель|Elder Gatherer|Он живёт возле опустевших складов. Проверяет каждый угол, словно помнит, что именно лежало там прежде.|It lives beside empty stores and checks every corner, as though remembering exactly what used to lie there.
boss:shooter|Пиковик Пустоты|Void Lancer|Разведчики отмечали его узким проколом на карте. Расстояние не помогало: след появлялся там, где только что стоял наблюдатель.|Scouts marked it with a narrow puncture on their maps. Distance did not help: the mark appeared where the observer had just stood.
boss:charger|Прорыватель|Breacher|Один переход котловины носит его имя. Это не памятник победе: прежний проход исчез, когда огромная особь впервые вышла на поверхность.|A basin crossing bears its name. It commemorates no victory. The former passage vanished when the creature first reached the surface.
boss:summoner|Роевой разум|Brood Mind|Его принимали за место скопления мелких существ. Только пустая оболочка показала, что у стаи было общее, очень старое тело.|It was mistaken for a gathering place for smaller creatures. An empty shell revealed that the swarm shared one very old body.
boss:aura|Титан ауры|Aura Titan|Он проходит мимо узлов, не касаясь их. Позади остаются оборванные линии и несколько секунд полной тишины.|It passes the nodes without touching them. Broken links and a few seconds of absolute silence remain behind.
boss:conductor|Чужой дирижёр|Stranger Conductor|Запись содержит всего один такт. После него приборы перешли на общий ритм, которого не было в настройках ни одного из них.|The recording contains one measure. Every instrument then adopted a shared rhythm present in none of their settings.
boss:architect|Слепой архитектор|Blind Architect|Существо достраивает контуры вокруг пустого центра. Исчезнувшие участки воссоздаёт точно, а проходы, оставленные строителями, каждый раз закрывает.|It completes outlines around an empty center. Missing sections are restored precisely. Every passage the builders left open is closed.
boss:null|Нулевой|The Null|До его появления в журнале есть время. После — тоже. Между ними нет изображения или ошибки записи. Только разница в числе вернувшихся.|There is a timestamp before it appears and another afterward. Between them lies neither image nor recording fault. Only a difference in the number who returned.
boss:stella_warden|Страж Стеллы|Stella Warden|Страж не покидает узел стабилизации надолго. В приказах нет команды нападать. Сохранилась одна строка: не допускать прекращения работы.|The warden never strays far from the stabilization node. Its orders contain no command to attack. One line survives: do not allow operation to cease.
boss:brood_queen|Матка роя|Brood Queen|Матка заняла командный каземат, где стены лучше держали тепло. Выводки сменялись, проходы зарастали, а её след у входа оставался прежним.|The queen settled in the command casemate, where walls held warmth longest. Broods changed and passages closed. Her tracks at the entrance remained the same.
boss:fleet_carrier|Носитель «Дальний берег»|Far Shore Carrier|Носитель сохранил список посадок, но не список взлётов. Дроны покидают отсеки с чистыми позывными. Назад он принимает уже знакомые.|The carrier retains a landing register but no departure list. Drones leave with clean callsigns. Those it accepts back are already familiar.
character:spherist|Сферист|Spherist|Первую сеть он собрал из узлов с разными разъёмами. В мастерской это считали временным решением. Когда пришло время заменить детали, сеть уже отвечала только ему. Сферист до сих пор берёт в забег переходник, которому больше нечего соединять.|He built his first Network from nodes with incompatible sockets. The workshop considered it temporary. By the time replacements arrived, the Network answered only to him. He still carries an adapter with nothing left to connect.
character:hunter|Охотник|Hunter|Охотник вернулся из разлома без карты. На ядре были выцарапаны риски: расстояния, паузы, направления. Его попросили восстановить маршрут. Он восстановил позиции тех, кто шёл следом.|The Hunter returned without a map. Scratches covered the Core: distances, pauses, directions. Asked to reconstruct his route, he reconstructed the positions of those following him.
character:engineer|Инженер|Engineer|Его первая должность называлась смотритель резервной линии. За семь лет резерв не понадобился ни разу. В день аварии он оказался единственной работающей частью станции. Инженер не любит, когда запасной узел называют лишним.|His first post was keeper of the reserve line. It went unused for seven years. On the day of the accident, it became the station's only working system. The Engineer dislikes hearing a spare node called unnecessary.
character:berserker|Берсерк|Berserker|На ядре остался вмятый участок брони. Новый кожух давно готов, но Берсерк откладывает замену. По старому металлу он слышит, насколько близко подошла стая.|A dent remains in the Core's armor. A replacement casing has long been ready. The Berserker postpones the work. Through the old metal, he can hear how close the pack has come.
character:alchemist|Алхимик|Alchemist|Она подписывает сосуды временем, а не названием содержимого. Та же смесь через час ведёт себя иначе, через день — снова иначе. В полевом журнале больше зачёркнутых дат, чем формул.|She labels vessels with times rather than contents. The same mixture behaves differently an hour later, and differently again the next day. Her journal contains more crossed-out dates than formulas.
character:architect|Архитектор|Architect|Архитектор чертит сеть до установки первого узла. На полях остаётся свободный участок. Когда-то там стояла сфера напарника. Перестраивать схему целиком он пока не научился.|The Architect draws the Network before placing its first node. A space remains at the edge. A partner's Sphere once stood there. He has not learned to redraw the plan completely.
character:conductor|Дирижёр|Conductor|После потери связи он несколько суток удерживал ритм вручную. Часы остановились, а узлы продолжали отвечать. Дирижёр вернулся, но считает паузы так, словно рядом всё ещё нет передатчика.|After communications failed, he maintained the rhythm by hand for days. Clocks stopped; the nodes kept answering. He returned, but still counts pauses as though no transmitter were nearby.
character:oracle|Оракул|Oracle|Оракул не отвечает сразу. Сначала она отодвигает предмет, которого ещё никто не собирался касаться. В её комнате мало вещей; на стенах много следов от прежних полок.|The Oracle never answers immediately. First she moves an object no one has intended to touch. Her room holds few belongings. The walls bear marks from former shelves.
character:voidwalker|Странник Пустоты|Voidwalker|В журнале переходов его имя записано дважды в одну минуту, на противоположных концах маршрута. Обе подписи подлинные. Странник интересуется только тем, кто поставил вторую.|The transit log records his name twice in one minute, at opposite ends of the route. Both signatures are authentic. He wants to know only who wrote the second.
character:fractal|Фрактал|Fractal|Фрактал хранит несколько версий одной схемы. В каждой исправлена другая ошибка, и ни одна не завершена. Перед выходом он раскладывает их рядом. На обратном пути иногда появляется ещё один лист.|He keeps several versions of one design. Each corrects a different mistake; none is finished. Before leaving, he lays them side by side. Another sheet sometimes appears on his return.
";
  private const string Roles=@"
role:3:grunt|Сколок|Chipling|Сколок держится у родной породы. После ухода в стене остаётся выемка, слишком гладкая для естественного излома.|It stays beside its parent rock. The hollow left in the wall is too smooth to be a natural fracture.
role:3:swarmer|Хрустальный осколок|Crystal Splinter|Его считали обломком, пока образцы не сменили места в ящике. Крышку стали запирать с двух сторон.|It was treated as debris until samples changed places inside the case. The lid was then locked from both sides.
role:3:charger|Резец|Cutter|Его борозды служили геодезистам ориентиром. Позже выяснилось, что все они сходятся у места стоянки.|Surveyors used its furrows as landmarks. They later found that all the tracks converged at their camp.
role:3:tank_guard|Друзовый страж|Cluster Guard|Внутри друзы видны наконечники старых буров. Кристалл сомкнулся вокруг них и продолжил расти.|Old drill tips are visible inside the cluster. The crystal closed around them and kept growing.
role:3:ranged|Гранёный стрелок|Facet Shooter|Передняя трещина похожа на след инструмента. Она есть и у молодых особей, никогда не видевших буровых установок.|The front crack resembles a tool mark. Even young specimens that have never seen a drilling rig bear it.
role:3:splitter|Семенная друза|Seed Cluster|В прозрачном теле лежат уже огранённые ядра. При движении они стучат друг о друга, как камни в закрытой коробке.|Faceted cores lie inside its transparent body. They knock together as it moves, like stones in a closed box.
role:3:healer|Сшиватель граней|Facet Mender|Тонкие нити тянутся к соседним кристаллам. После обвала они восстанавливаются прежде, чем оседает пыль.|Thin filaments reach neighboring crystals. After a collapse, they reform before the dust settles.
role:3:bomber|Напряжённая жеода|Strained Geode|Снаружи жеода кажется цельной. Внутри каждое отражение смещено относительно соседнего. Долго смотреть в неё неприятно.|The geode looks whole outside. Inside, each reflection is displaced from the next. Watching it for long is uncomfortable.
role:3:leech|Тягловик|Drawstone|На плане отмечено место, где исчезали детали. Рядом лежал гладкий камень, который никто не включал в опись.|The plan marks where small parts disappeared. A smooth stone lay nearby. No one entered it in the inventory.
role:3:sniper|Игольчатая линза|Needle Lens|Сквозь неё видна дальняя стена даже за непрозрачной породой. Первую линзу потеряли вместе с наблюдателем.|Its central facet shows a distant wall through opaque rock. The first lens was lost with its observer.
role:3:disruptor|Камертон разлома|Fault Tuning Fork|Отростки колеблются с едва заметной разницей. Приборы между ними дают верные показания, но каждый раз разные.|Its prongs vibrate at slightly different rates. Instruments between them give accurate readings that change every time.
role:3:anchor|Опорный монолит|Keystone Monolith|Он висит над провалившейся опорой. Снизу сохранился отпечаток балки, исчезнувшей много лет назад.|It hangs above a collapsed support. Its underside retains the imprint of a beam lost years ago.
role:3:phase|Полая грань|Hollow Facet|Образец был тяжелее сосуда. На следующем привале сосуд оказался полон, а образец исчез.|The specimen outweighed its carrier vessel. At the next stop, the vessel was full and the specimen gone.
role:3:scavenger|Минеральщик|Mineral Collector|В следе попадаются отполированные головки крепежа. Остальные части механизмов он оставляет там, где нашёл.|Polished fastener heads appear in its trail. It leaves the rest of each mechanism where it found it.
role:3:corruptor|Больной кристалл|Clouded Crystal|Серая прожилка выходит наружу у сочленений. В соседних образцах такие появились уже после перевозки.|A gray vein reaches the surface at its joints. Similar veins appeared in neighboring samples after transport.
role:4:grunt|Блуждающий импульс|Wandering Pulse|Он возвращается к месту рождения после каждого обхода. Передатчика там нет, но пауза перед выходом всегда одинакова.|It returns to its birthplace after every circuit. No transmitter remains, but the pause before departure is always the same.
role:4:swarmer|Искровой рой|Spark Swarm|Приборы принимали его за помеху. Потом искры начали огибать препятствия и ждать друг друга.|Instruments treated it as interference. Then the sparks began moving around obstacles and waiting for one another.
role:4:charger|Грозовой клин|Thunder Wedge|На опорах остаются ветвистые ожоги. Все они направлены к давно погасшему маяку.|Branching burns remain on the supports. Every mark points toward the long-extinguished beacon.
role:4:tank_guard|Штормовой кокон|Storm Cocoon|Пыль снаружи оболочки движется по кругу. Внутри неподвижно висит один тёмный осколок.|Dust circles outside its shell. A single dark fragment hangs motionless within.
role:4:ranged|Дуговой стрелок|Arc Shooter|Дуга повторяет контур старой антенны. В момент разряда видны даже её сломанные растяжки.|The arc traces an old antenna's outline. Even its broken stays become visible during discharge.
role:4:splitter|Разветвитель|Branching Pulse|Маршрут нарисован одним движением пера. На обратном пути линия раздваивается, и обе ветви возвращаются к началу.|Its route was drawn in one stroke. On the return, the line divides and both branches reach the start.
role:4:healer|Сшиватель тока|Current Mender|Он останавливается у оборванных проводников. Между ними возникает свет, хотя в старой цепи больше нет питания.|It pauses beside severed conductors. Light bridges them, though the old circuit has no power source.
role:4:bomber|Грозовой пузырь|Thunder Blister|Пузыри растут на встрече двух потоков. Уцелевшие дорожки обходят эти места широкими дугами.|Blisters grow where opposing currents meet. Surviving paths curve widely around these places.
role:4:leech|Обратный ток|Return Current|Выключенные приборы рядом оживают на долю секунды. После этого их накопители совершенно пусты.|Switched-off instruments wake for a fraction of a second. Their capacitors are completely empty afterward.
role:4:sniper|Прямая молния|Straight Lightning|Её след не ветвится. Первые фотографии сочли повреждёнными: одна ровная линия проходила через несколько кадров.|Its trail never branches. The first photographs were judged damaged: one straight line crossed several frames.
role:4:disruptor|Срыватель ритма|Beat Breaker|Один хронометр потерял за смену семь секунд. Второй, стоявший рядом, показал лишние семь.|One watch clock lost seven seconds during a shift. The clock beside it gained seven.
role:4:anchor|Узел грозы|Storm Knot|Сквозь него проходят встречные потоки. Ни один не выходит под тем углом, под которым вошёл.|Opposing currents pass through it. None leaves at the angle it entered.
role:4:phase|Промежуток|Interval|Он виден между яркими вспышками. Там, где должен быть след, поверхность остаётся холодной.|It appears between bright flashes. The surface where its trail should be remains cold.
role:4:scavenger|Сборщик искр|Spark Collector|Он собирает слабые разряды после фронта. Далеко позади шторма ещё долго движется маленький светящийся комок.|It gathers faint discharges behind the front. A small glowing knot can be seen long after the storm passes.
role:4:corruptor|Грязный разряд|Fouled Discharge|Дуга оставляет на металле чёрный налёт. Дорожки под ним целы, но ток по ним не идёт.|The arc leaves a black deposit on metal. Traces beneath it are intact but no longer conduct.
role:5:grunt|Черновик тела|Body Draft|У записи нет даты завершения. Архив извлекает её из временного хранилища и снова помечает как незавершённую.|The record has no completion date. The archive retrieves it from temporary storage and marks it unfinished once more.
role:5:swarmer|Беглая копия|Runaway Copy|Она отделилась до окончания сверки. В маршруте остались повороты, которых нет ни на одной уцелевшей карте.|It separated before verification ended. Its route contains turns absent from every surviving map.
role:5:charger|Повтор последнего удара|Last Impact Replay|В отчёте уцелел только момент столкновения. Архив восстанавливает его точно, не зная, что было до и после.|Only the collision survived in the report. The archive reconstructs it precisely, knowing nothing of before or after.
role:5:tank_guard|Хранитель оболочки|Shell Keeper|Защитные слои не совпадают по форме. Но каждый закрывает трещину предыдущего и держится на нём.|The protective layers do not match. Each covers a crack in the previous one and clings to it.
role:5:ranged|Остаточный стрелок|Residual Shooter|Движение орудия сохранилось целиком. Имя владельца и цель были утрачены при первой попытке восстановления.|The weapon's movement survived intact. Its owner's name and target were lost during the first restoration attempt.
role:5:splitter|Резервная копия|Backup Copy|Запись успела сохранить себя в нескольких местах. Каждая версия считает остальные ошибкой восстановления.|The record saved itself in several locations. Each version considers the others restoration errors.
role:5:healer|Реставратор|Restorer|Он сшивает разрывы, не сверяясь с исходником. Чужие фрагменты приживаются так прочно, что архив перестаёт различать границы.|It closes gaps without the original. Foreign fragments take hold so firmly that the archive loses their boundaries.
role:5:bomber|Аварийный сброс|Emergency Dump|Протокол требовал уничтожать носитель после переполнения. Счётчик сброшен, а команда осталась в очереди.|The protocol required destruction after overflow. The counter was reset. The command remains queued.
role:5:leech|Сборщик имён|Name Collector|В журнале посещений остаются пустые строки. Время верно; поле имени словно никогда не заполняли.|Blank lines appear in the visitor log. Arrival times are correct. The name fields look untouched.
role:5:sniper|Последний свидетель|Last Witness|Запись заканчивается точным выстрелом. При каждом воспроизведении стрелок заново находит точку, откуда на него смотрели.|The recording ends with one precise shot. On each replay, the shooter finds the position from which it was watched.
role:5:disruptor|Редактор|Redactor|Он не уничтожает запись. Убирает короткий участок, после которого остальное перестаёт иметь смысл.|It does not destroy a record. It removes a short passage after which the rest no longer makes sense.
role:5:anchor|Неподвижный адрес|Fixed Address|Хранилище переносили много раз. В указателе осталась старая координата, и что-то по-прежнему занимает это место.|The vault was relocated many times. Its index retains an old coordinate. Something still occupies that position.
role:5:phase|Пропуск|Omission|Между соседними номерами описи оставлено место. Удалить его нельзя: после сверки промежуток появляется снова.|A space separates consecutive inventory numbers. It cannot be removed. After verification, the gap returns.
role:5:scavenger|Сборщик утраченного|Lost Fragment Gatherer|Он несёт к закрытой двери обрывки голосов и части тел. Дверь не открывается. Куча растёт.|It brings scraps of voices and body parts to a closed door. The door never opens. The pile grows.
role:5:corruptor|Повреждённый слепок|Damaged Cast|На нём видны следы несовместимых тел. Иногда одно движение заканчивается прежде, чем начинается другое.|Traces of incompatible bodies cover it. Sometimes one movement ends before the next begins.
role:1:grunt|Пикет «Шов»|Seam Picket|Пикет остался между двумя исчезающими рядами огней. Командный модуль до сих пор запрашивает разрешение сменить позицию.|The picket remained between two fading lines of lights. Its command module still requests permission to change station.
role:1:swarmer|Перехватчик «Игла»|Needle Interceptor|На борту нет места для запасного реактора. Пилоты меняли машины после каждого вылета. Последняя смена не состоялась.|There is no room for a spare reactor. Pilots exchanged craft after every sortie. The final exchange never took place.
role:1:charger|Корвет «Заслон»|Screen Corvette|На броне остались следы буксирных захватов. Корвет вытаскивал повреждённые суда из строя; теперь сам закрывает разрывы в колонне.|Tow-clamp scars remain on its armor. It pulled damaged vessels out of formation. It now fills the gaps itself.
role:1:tank_guard|Броненосец «Порог»|Threshold Ironclad|В борт вварены листы с трёх кораблей. Внутри одного сохранилось расписание вахт, которое некому читать.|Plates from three ships reinforce its flank. One retains a watch schedule on the inside. No one remains to read it.
role:1:ranged|Канонерка «Вязь»|Ligature Gunship|В журналах эти суда отмечали чертой. Стрелок ставил вторую, когда возвращался. В последнем журнале вторых черт нет.|Logs marked these gunships with a stroke. The gunner added a second after returning. The final log contains no second strokes.
role:1:splitter|Кассетный тендер|Cassette Tender|Тендер перевозил секции орбитальных доков. Их крепления отпущены, но в грузовых пазах ещё удерживаются малые корпуса.|It carried orbital dock sections. Their restraints are released, but smaller hulls still cling to its cargo slots.
role:1:healer|Ремонтник «Латка»|Patch Repair Ship|Манипуляторы не различают старые и новые повреждения. Ремонтник раз за разом возвращается к пробоинам последнего боя.|Its arms cannot distinguish old damage from new. It keeps returning to holes left in the final battle.
role:1:bomber|Минный шлюп|Mine Sloop|Таблички у люков запрещают включать тягу рядом с боезапасом. Все они обуглены с одной стороны.|Signs beside the hatches forbid ignition near munitions. Every sign is scorched on one side.
role:1:leech|Сборщик «Отток»|Drain Collector|Он подбирал за флотом разряженные блоки. Грузовые полости полны, а маршрут сбора всё ещё не закончен.|It followed the fleet collecting spent cells. Its holds are full. The collection route remains unfinished.
role:1:sniper|Фрегат «Тонкая грань»|Fine Edge Frigate|Фрегат строили для стрельбы через щели в щитах. Прицельные приводы пережили верфь и экипаж, не потеряв калибровку.|Built to fire through shield gaps, its targeting drives outlived yard and crew without losing calibration.
role:1:disruptor|Узел связи «Хор»|Choir Command Node|В памяти осталось четырнадцать командирских голосов. При передаче приказа звучат все сразу. Корабли по-прежнему понимают их.|Fourteen command voices remain. They speak together whenever an order is sent. The ships still understand.
role:1:anchor|Монитор «Неподвижный»|Stillwater Monitor|У корпуса нет походного двигателя. В мирное время его буксировали на орбиту. С последней позиции он не ушёл.|It has no cruising engine. In peacetime it was towed into orbit. It never left its final station.
role:1:phase|Разведчик «Изнанка»|Far Side Scout|Разведчик первым проверил проход через разлом. Запись прибытия оказалась старше записи отбытия на одиннадцать минут.|It tested the passage first. Its arrival record predates its departure by eleven minutes.
role:1:scavenger|Буксир «Чужой борт»|Stray Hull Tug|На захватах висят кольца разных верфей. Буксир находил корабли по аварийным маякам и редко дожидался ответа.|Rings from different yards hang from its clamps. It found ships by distress beacons and seldom waited for an answer.
role:1:corruptor|Постановщик помех|Jamming Vessel|Антенны обращены внутрь строя. Приказ подавлять чужую связь был последним, в котором ещё указывался противник.|Its antennas point into the formation. The order to suppress foreign signals was the last to name an enemy.
role:2:grunt|Казематный рабочий|Casemate Worker|Выводки расчистили лестницы. Ступени стали шире, стены — тоньше. Строители бастиона уже не смогли бы пользоваться этими ходами.|The broods cleared the stairs. Steps grew wider and walls thinner. The bastion's builders could no longer use these passages.
role:2:swarmer|Молодой бегунок|Brood Runner|На мягком панцире видны складки выводной оболочки. Бегунок не знает переходов и повторяет движения старших.|Creases from its hatching membrane remain on the shell. It does not know the passages and follows the older brood.
role:2:charger|Воротный таран|Gate Ram|Поколения этих особей выводили у запертых ворот. Ворота рухнули, но широкий лоб остался у всего выводка.|Generations were bred beside the sealed gates. The gates fell. Every member of the brood still carries the broad forehead.
role:2:tank_guard|Щитоносец улья|Hive Shieldbearer|Под тёмными пластинами лежит молодой панцирь. Старую броню щитоносцы передают вместе с местом в дозоре.|A young shell lies beneath the dark plates. Shieldbearers inherit both old armor and a place in the patrol.
role:2:ranged|Споровый плевун|Spore Spitter|В горловых мешках хранится пыль нижних камер. В пустом бастионе она оседает долго; плевуна узнавали по следам на стенах.|Its throat sacs hold dust from the lower chambers. It hangs in the empty bastion. Marks on the walls betrayed its passing.
role:2:splitter|Носитель кладки|Clutch Bearer|Молодь цепляется за складки брюха. Даже в заброшенном коридоре носитель никогда не бывает один.|Young cling to folds beneath its abdomen. Even in an abandoned corridor, the bearer is never alone.
role:2:healer|Смоляной кормилец|Resin Nurse|Смолу собирают с корней улья. Кормилец разносит её по дозорам; старые солдаты узнают его запах в темноте.|Resin comes from the hive roots. The nurse carries it between patrols. Old soldiers know its scent in darkness.
role:2:bomber|Разрывник|Burst Sac|Выводная камера находится далеко от остальных. Постоянного входа в ней нет: после каждого цикла насекомые прорезают новый.|Its hatching chamber stands apart. There is no permanent entrance. After each cycle, the insects cut a new one.
role:2:leech|Колодезная пиявка|Cistern Leech|Цистерны высохли давно. Пиявки остались возле труб и научились находить другие тёплые потоки.|The cisterns dried out long ago. Their leeches remained beside the pipes and learned to find other warm currents.
role:2:sniper|Игломёт|Needle Caster|Иглы формируются в пазах панциря. Под старыми бойницами их лежит столько, что не видно камня.|Needles form in grooves along its shell. So many lie beneath the old embrasures that the stone is hidden.
role:2:disruptor|Глушильщик|Hush Drone|Его замечают по отсутствию шороха. В тихой камере улья рядом с ним не слышно даже собственных шагов.|It is noticed by the missing rustle. In the hive's quiet chamber, even footsteps seem absent beside it.
role:2:anchor|Заторник|Tunnel Plug|Эту особь вырастили вокруг прохода. Двигаясь, она сдирает следы кладки с панциря. Проход всё ещё закрыт.|It grew around a passage. Moving scrapes masonry from its shell. The passage remains closed.
role:2:phase|Трещинник|Crack Walker|Ночью дозоры слышали скрежет внутри стен. Кладка оставалась целой, а снаружи появлялись следы лап.|At night, patrols heard scraping inside the walls. The masonry stayed intact, with footprints appearing outside.
role:2:scavenger|Костяной сборщик|Bone Gatherer|Он несёт в гнездо всё, что помещается между жвалами. В кучах обломков находят застёжки гарнизонной формы.|It carries anything fitting between its jaws to the nest. Garrison uniform fasteners appear in the piles.
role:2:corruptor|Плесневик|Mold Carrier|Налёт впервые появился на закрытых аптечных ящиках. Потом они вскрылись изнутри, и по коридору прошёл первый носитель.|The growth first appeared on sealed medical crates. They opened from within, and the first carrier crossed the corridor.
